import React, { useState } from 'react';
import './RecipeGenerator.css';

const RecipeGenerator = () => {
  const [ingredients, setIngredients] = useState('');
  const [servings, setServings] = useState(4);
  const [dietaryRestrictions, setDietaryRestrictions] = useState([]);
  const [cuisine, setCuisine] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [recipes, setRecipes] = useState([]);
  const [missingIngredients, setMissingIngredients] = useState([]);
  const [error, setError] = useState('');

  const cuisineOptions = [
    'Andhra Pradesh', 'Bengali', 'Bihari', 'Gujarati', 'Hyderabadi',
    'Karnataka', 'Kashmiri', 'Kerala', 'Maharastrian', 'Marwari',
    'Rajasthani', 'Sindhi', 'Tamil Nadu', 'Uttar Pradesh', 'Punjabi', 'Indian'
  ];

  const dietaryOptions = ['Vegetarian', 'Non-Vegetarian'];

  const handleDietaryChange = (option) => {
    setDietaryRestrictions(prev =>
      prev.includes(option)
        ? prev.filter(item => item !== option)
        : [...prev, option]
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setRecipes([]);
    setMissingIngredients([]);

    if (!ingredients.trim()) {
      setError('Please enter some ingredients.');
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch('http://127.0.0.1:8000', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ingredients: ingredients.split(',').map(i => i.trim()),
          servings,
          cuisine,
          dietaryRestrictions
        })
      });

      if (!response.ok) {
        throw new Error(`Server responded with ${response.status}`);
      }

      const data = await response.json();
      console.log('✅ API Response:', data);

      setRecipes(data.recipes || []);
      setMissingIngredients(data.missing_ingredients || []);
    } catch (err) {
      console.error('❌ Fetch error:', err);
      setError('Failed to connect to backend. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <section className="recipe-generator">
      <div className="container">
        <div className="generator-header">
          <h1 className="page-title">🍳 Smart Recipe Generator</h1>
          <p className="page-subtitle">
            Enter ingredients, and AI will generate perfect recipes with missing items!
          </p>
        </div>

        <div className="generator-content">
          <form onSubmit={handleSubmit} className="generator-form card">
            <div className="form-group">
              <label className="form-label">🥕 Available Ingredients</label>
              <textarea
                className="form-input form-textarea"
                placeholder="e.g. rice, onion, tomato, chicken..."
                value={ingredients}
                onChange={(e) => setIngredients(e.target.value)}
                required
              />
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">👥 Servings</label>
                <input
                  type="number"
                  className="form-input"
                  min="1"
                  max="20"
                  value={servings}
                  onChange={(e) => setServings(parseInt(e.target.value))}
                />
              </div>

              <div className="form-group">
                <label className="form-label">🌍 Cuisine</label>
                <select
                  className="form-input"
                  value={cuisine}
                  onChange={(e) => setCuisine(e.target.value)}
                >
                  <option value="">Any Cuisine</option>
                  {cuisineOptions.map((option) => (
                    <option key={option} value={option}>{option}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">🥗 Dietary Preference</label>
              <div className="dietary-options">
                {dietaryOptions.map((option) => (
                  <label key={option} className="dietary-option">
                    <input
                      type="checkbox"
                      checked={dietaryRestrictions.includes(option)}
                      onChange={() => handleDietaryChange(option)}
                    />
                    <span>{option}</span>
                  </label>
                ))}
              </div>
            </div>

            {error && <p className="error-text">{error}</p>}

            <button
              type="submit"
              className="btn btn-primary btn-large w-full"
              disabled={isLoading}
            >
              {isLoading ? 'Generating Recipes...' : 'Generate Recipes ✨'}
            </button>
          </form>

          {/* ✅ Missing Ingredients */}
          {missingIngredients.length > 0 && (
            <div className="missing-ingredients card">
              <h3>❌ Missing Ingredients</h3>
              <ul>
                {missingIngredients.map((item, index) => (
                  <li key={index}>{item}</li>
                ))}
              </ul>
            </div>
          )}

          {/* ✅ Recipes */}
          {recipes.length > 0 && (
            <div className="recipe-results">
              <h2>🍽 Recommended Recipes</h2>
              <div className="recipe-grid">
                {recipes.map((recipe, index) => (
                  <div key={index} className="recipe-card card">
                    <img src={recipe.image} alt={recipe.name} className="recipe-image" />
                    <h3>{recipe.name}</h3>
                    <p><strong>Cuisine:</strong> {recipe.cuisine}</p>
                    <p><strong>Time:</strong> {recipe.time_to_prepare_minutes} mins</p>
                    <h4>Ingredients:</h4>
                    <ul>
                      {recipe.ingredients.map((ing, idx) => (
                        <li key={idx}>
                          {ing.available ? '✅' : '❌'} {ing.name} ({ing.amount})
                        </li>
                      ))}
                    </ul>
                    <h4>Instructions:</h4>
                    <ol>
                      {recipe.instructions.map((step, i) => (
                        <li key={i}>{step}</li>
                      ))}
                    </ol>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default RecipeGenerator;
